function bowIcon(charge) {
  return pxDraw(set => {
    for (let a = 0; a <= 90; a += 4) { const t = a * Math.PI / 180; const x = Math.round(2 + 12 * Math.cos(t)), y = Math.round(13 - 12 * Math.sin(t)); set(x, y, a % 12 === 0 ? HANDLE_D : HANDLE); }
    const pull = Math.round((charge || 0) * 3);
    for (let i = 0; i <= 12; i++) set(2 + i - (i > 3 && i < 9 ? pull : 0) * 0, 1 + i, [200, 200, 200]);
    if (charge) { for (let i = 0; i < 9; i++) set(3 + i - pull, 10 - i + pull, HANDLE); set(12 - pull, 1 + pull, [180, 180, 180]); }
  });
}
