function planks2(px, r, base) {
  for (let b = 0; b < 4; b++) {
    const tone = 0.92 + r() * 0.16, seam = (b * 7 + 3 + (r() * 3 | 0)) % 16; const bc = sh(base, tone);
    for (let x = 0; x < 16; x++) for (let yy = 0; yy < 4; yy++) { const y = b * 4 + yy; let c = bc; if (yy === 3) c = sh(base, 0.58); else if (yy === 0) c = sh(bc, 1.1); else if (x === seam) c = sh(base, 0.66); px(x, y, c); }
    for (let g = 0; g < 4; g++) { const y = b * 4 + 1 + (r() * 2 | 0); let x = r() * 16 | 0; const len = 2 + r() * 5 | 0; for (let i = 0; i < len; i++) px(x + i, y, sh(bc, 0.84)); }
    if (r() < 0.5) { const x = (seam + 2 + (r() * 10 | 0)) % 16; px(x, b * 4 + 1, sh(base, 0.55)); }
  }
}
