function bark(px, r, base, deep, light) {
  const cols = []; let x0 = r() * 3 | 0; while (x0 < 16) { cols.push(x0); x0 += 3 + (r() * 2 | 0); }
  for (let x = 0; x < 16; x++) { const k = 0.9 + r() * 0.2; for (let y = 0; y < 16; y++) px(x, y, sh(base, k + (r() - 0.5) * 0.08)); }
  for (const cx of cols) { let x = cx; for (let y = 0; y < 16; y++) { px(x, y, deep); px(x + 1, y, sh(base, 0.82)); if (r() < 0.25) x += r() < 0.5 ? -1 : 1; } }
  for (let i = 0; i < 10; i++) px(r() * 16 | 0, r() * 16 | 0, light);
}
