    let d1 = 99, d2 = 99, k = 1, ddx = 0, ddy = 0; for (const p of pts) for (let ox = -16; ox <= 16; ox += 16) for (let oy = -16; oy <= 16; oy += 16) { const dx = x + 0.5 - p[0] - ox, dy = y + 0.5 - p[1] - oy, d = Math.hypot(dx, dy); if (d < d1) { d2 = d1; d1 = d; k = p[2]; ddx = dx; ddy = dy; } else if (d < d2) d2 = d; }
