function doorTex(top) { return (px, r) => { planks2(px, r, [150, 112, 66]); for (let i = 0; i < 16; i++) { px(0, i, [84, 60, 34]); px(15, i, [84, 60, 34]); px(1, i, [176, 138, 86]); } if (top) { for (let i = 0; i < 16; i++) px(i, 0, [84, 60, 34]); for (let y = 3; y < 11; y++) for (let x = 3; x < 13; x++) px(x, y, (x === 3 || x === 12 || y === 3 || y === 10 || x === 7 || x === 8) ? [84, 60, 34] : [0, 0, 0, 0]); } else { for (let i = 0; i < 16; i++) px(i, 15, [84, 60, 34]); for (let y = 3; y < 12; y++) for (let x = 3; x < 13; x++) if (x === 3 || x === 12 || y === 3 || y === 11) px(x, y, [104, 76, 44]); px(12, 1, [230, 200, 90]); px(13, 1, [230, 200, 90]); px(12, 0, [230, 200, 90]); } }; }
