function matchRecipe(grid, gw) {
  const gh = grid.length / gw; let minx = 9, miny = 9, maxx = -1, maxy = -1; const items = [];
  for (let y = 0; y < gh; y++) for (let x = 0; x < gw; x++) { const s = grid[y * gw + x]; if (s) { minx = Math.min(minx, x); maxx = Math.max(maxx, x); miny = Math.min(miny, y); maxy = Math.max(maxy, y); items.push(s.id); } }
  if (maxx < 0) return null; const w = maxx - minx + 1, h = maxy - miny + 1;
  for (const r of RECIPES) {
    if (r.shapeless) {
      if (r.shapeless.length !== items.length) continue; const pool = items.slice(); let ok = true;
      for (const need of r.shapeless) { const i = pool.findIndex(id => need.includes(id)); if (i < 0) { ok = false; break; } pool.splice(i, 1); }
      if (ok) return r; continue;
    }
    if (r.w !== w || r.h !== h) continue;
    for (const mirror of [false, true]) {
      let ok = true;
      for (let y = 0; y < h && ok; y++) for (let x = 0; x < w && ok; x++) {
        const row = r.rows[y]; const ch = row[mirror ? (w - 1 - x) : x] || ' ';
        const s = grid[(miny + y) * gw + minx + x];
        if (ch === ' ') { if (s) ok = false; } else { if (!s || !r.keys[ch].includes(s.id)) ok = false; }
      }
      if (ok) return r;
    }
  }
  return null;
}
