function itemCat(id) { const it = IT[id]; if (!it) return null; if (it.key === 'book' || it.key === 'enchanted_book') return 'book'; if (it.armor !== undefined) return 'armor' + it.armor; if (it.tool && it.tool !== 'fns') return it.tool; return null; }
function enchFits(k, id) { const c = itemCat(id); if (!c) return false; if (c === 'book') return true; if (IT[id].wings) return ENCH[k].for.includes('any'); const f = ENCH[k].for; if (f.includes('any')) return !!IT[id].dur; if (c.startsWith('armor') && f.includes('armor')) return true; return f.includes(c); }
function enchLvl(st, k) { return st && st.e && st.e[k] || 0; }
