    super(x + 0.5, y, z + 0.5, 0.49, 0.98); this.fuse = fuse; this.vel.set((Math.random() - 0.5), 4, (Math.random() - 0.5));
    this.mat = G.matSolid.clone(); this.mat.onBeforeCompile = G.matSolid.onBeforeCompile; this.mesh = new THREE.Mesh(blockCubeGeo(BID.tnt, 0.98), this.mat); G.scene.add(this.mesh);
