    const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: new THREE.CanvasTexture(c), depthWrite: false })); sp.scale.set(1.7, 0.32, 1); sp.position.y = 2.3; this.mesh.add(sp);
