      this.eatT -= dt; f = -1; st = this.strafe * 0.5; if (Math.random() < dt * 6) Particles.spawn(this.pos.x, this.pos.y + 1.5, this.pos.z, [1, 0.85, 0.2], 2, 1, 0.4, 8, 0.2);
      if (this.eatT <= 0) { this.hp = Math.min(20, this.hp + 9); Snd.play('burp', 0.5 * G.vol(this.pos)); }
