World.prototype.lightAt = function (x, y, z) {
  const bx = Math.floor(x), by = Math.floor(y), bz = Math.floor(z); let sky = 0; if (this.dim === 'overworld') { const t = this.topAt(bx, bz); sky = by > t ? 1 : Math.max(0.04, 1 - (t - by) * 0.13); }
  let m = 0; const cx = bx >> 4, cz = bz >> 4; for (let dx = -1; dx <= 1; dx++) for (let dz = -1; dz <= 1; dz++) { const c = this.chunks.get(ckey(cx + dx, cz + dz)); if (!c) continue; const ox = c.cx * 16, oz = c.cz * 16; for (const L of c.lights) { const v = L[3] - (Math.abs(bx - ox - L[0]) + Math.abs(by - L[1]) + Math.abs(bz - oz - L[2])); if (v > m) m = v; } }
  return Math.max(sky * dayU.value, m / 15, minU.value);
};

World.prototype.lightParts = function (x, y, z) {
  const bx = Math.floor(x), by = Math.floor(y), bz = Math.floor(z); let sky = 0; if (this.dim === 'overworld') { const t = this.topAt(bx, bz); sky = by > t ? 1 : Math.max(0, 1 - (t - by) * 0.13); }
  let m = 0; const cx = bx >> 4, cz = bz >> 4; for (let dx = -1; dx <= 1; dx++) for (let dz = -1; dz <= 1; dz++) { const c = this.chunks.get(ckey(cx + dx, cz + dz)); if (!c) continue; const ox = c.cx * 16, oz = c.cz * 16; for (const L of c.lights) { const v = L[3] - (Math.abs(bx - ox - L[0]) + Math.abs(by - L[1]) + Math.abs(bz - oz - L[2])); if (v > m) m = v; } }
  return [sky, m / 15];
};

