    const push = (e, isP) => { const ec = new THREE.Vector3(e.pos.x, e.pos.y + (isP ? 0.2 : e.h / 2), e.pos.z), d = ec.distanceTo(c); if (d > 3.2) return; const f = 1 - d / 3.2, dir = ec.sub(c); if (dir.lengthSq() < 0.01) dir.set(0, 1, 0); dir.normalize();
      if (isP) { e.vel.x += dir.x * 12 * f; e.vel.z += dir.z * 12 * f; e.vel.y = Math.max(e.vel.y, 6 + 9 * f + Math.max(0, dir.y) * 4); e.fallDist = 0; e.windT = 1.2; e.windBase = e.pos.y; e.windApex = e.pos.y; } else if (!e.T.noPush) { e.vel.x += dir.x * 14 * f; e.vel.z += dir.z * 14 * f; e.vel.y = Math.max(e.vel.y, 5 + 7 * f); } };
