    const w = G.world; for (let dx = -2; dx <= 2; dx++) for (let dy = -1; dy <= 2; dy++) for (let dz = -2; dz <= 2; dz++) { const X = Math.floor(c.x) + dx, Y = Math.floor(c.y) + dy, Z = Math.floor(c.z) + dz, id = w.getBlock(X, Y, Z); if (id === BID.fire) w.setBlock(X, Y, Z, 0); }
