// ================= PATRULHAS, INVASÕES (Mau Presságio) E MOBS DA MANSÃO =================
G.raid = null;
const spawnAt = (t, x, z, opt) => { const w = G.world, h = w.heightAt(Math.floor(x), Math.floor(z)); if (h <= SEA) return null; const e = makeMob(t, x + 0.5, h + 1.05, z + 0.5); Object.assign(e, opt || {}); G.entities.push(e); return e; };
const _st = G.spawnTick;
G.spawnTick = function (dt) {
  const r = _st.call(this, dt); const w = this.world, p = this.player; if (!w || w.dim !== 'overworld' || p.mode === 'spectator') return r;
  this.illT = (this.illT || 0) - dt; if (this.illT > 0) return r; this.illT = 1.5;
  // patrulha (aparece de vez em quando a partir do 2º dia)
  if (this.difficulty > 0 && !this.raid && this.day >= 1 && Math.random() < 0.012 && !this.entities.some(e => e.patrol && !e.dead) && !w.structsNear(p.pos.x, p.pos.z, 60, 'village').length) {
    const a = Math.random() * 6.28, d = 28 + Math.random() * 14, x = p.pos.x + Math.cos(a) * d, z = p.pos.z + Math.sin(a) * d; const pat = {};
    const cap = spawnAt('pillager', x, z, { captain: true, patrol: pat }); if (cap) { pat.lead = cap; const n = 1 + (Math.random() * 3 | 0); for (let i = 0; i < n; i++) spawnAt(Math.random() < 0.3 ? 'vindicator' : 'pillager', x + (Math.random() - 0.5) * 5, z + (Math.random() - 0.5) * 5, { patrol: pat }); }
  }
  // mansão: vingadores e invocadores lá dentro (quantidade limitada por mansão)
  if (this.difficulty > 0) for (const s of w.structsNear(p.pos.x, p.pos.z, 40, 'mansion')) {
    const k = 'mansion:' + s.x + ',' + s.z, st = w.bdata[k] || (w.bdata[k] = { ev: 2, vin: 10 }); if (st.ev + st.vin <= 0) continue;
    const near = this.entities.filter(e => e.mansion === k && !e.dead && !e.dying).length; if (near >= 4) continue;
    const fl = Math.random() < 0.5 ? 1 : 7, x = s.x + Math.floor((Math.random() - 0.5) * 26), z = s.z + (Math.random() < 0.5 ? -1 : 1) * (2 + Math.floor(Math.random() * 7)), y = s.y + fl;
    if (SOLID[w.getBlock(x, y, z)] || SOLID[w.getBlock(x, y + 1, z)] || !SOLID[w.getBlock(x, y - 1, z)] || Math.hypot(x - p.pos.x, z - p.pos.z) < 6) continue;
    const t = st.ev > 0 && Math.random() < 0.3 ? 'evoker' : st.vin > 0 ? 'vindicator' : st.ev > 0 ? 'evoker' : null; if (!t) continue; if (t === 'evoker') st.ev--; else st.vin--;
    const e = makeMob(t, x + 0.5, y + 0.05, z + 0.5); e.mansion = k; this.entities.push(e);
  }
  // começa a invasão: Mau Presságio + entrar numa vila
  const om = p.effects && p.effects.bad_omen;
  if (!this.raid && om && this.difficulty > 0 && p.mode === 'survival') { const v = w.structsNear(p.pos.x, p.pos.z, 34, 'village')[0]; if (v && Math.hypot(v.x - p.pos.x, v.z - p.pos.z) < 34) { delete p.effects.bad_omen; UI.dirtyEff = true; const lvl = om.lvl || 1; this.raid = { x: v.x, z: v.z, y: v.y, lvl, wave: 0, waves: Math.min(7, 2 + this.difficulty + (lvl > 1 ? 1 : 0)), t: 6, alive: [], maxHp: 1 }; UI.toast('Uma invasão está chegando! Defenda a vila!'); Snd.play('dragon', 0.4); Snd.play('portal', 0.7); } }
  return r;
};
function raidWave(R) {
  R.wave++; const n = R.wave, a0 = Math.random() * 6.28, list = [];
  for (let i = 0; i < 1 + n; i++) list.push('pillager'); for (let i = 0; i < n - 1; i++) list.push('vindicator'); if (n >= 3) list.push('evoker'); if (n === R.waves) { list.push('vindicator', 'pillager'); if (n >= 4) list.push('evoker'); }
  R.alive = []; for (const t of list) { const a = a0 + (Math.random() - 0.5) * 1.2, d = 34 + Math.random() * 6; const e = spawnAt(t, R.x + Math.cos(a) * d, R.z + Math.sin(a) * d, { raid: true }); if (e) { if (R.lvl >= 3) e.hp = e.T.hp * 1.3; R.alive.push(e); } }
  if (!R.alive.length) { const e = spawnAt('pillager', R.x + 8, R.z + 8, { raid: true }); if (e) R.alive.push(e); }
  R.maxHp = R.alive.reduce((s, e) => s + e.hp, 0); Snd.play('dragon', 0.5); UI.toast('Onda ' + n + '/' + R.waves + '!');
}
const _lp = G.updateHand;
G.updateHand = function (dt) {
  const R = this.raid; if (R && this.state === 'play') {
    const p = this.player, far = Math.hypot(R.x - p.pos.x, R.z - p.pos.z) > 110;
    if (this.world.dim !== 'overworld' || far || p.dead) { this.raid = null; this.entities.forEach(e => { if (e.raid) e.raid = false; }); UI.toast('A invasão terminou: derrota.'); }
    else {
      R.alive = R.alive.filter(e => !e.dead && !e.dying); const hp = R.alive.reduce((s, e) => s + Math.max(0, e.hp), 0);
      if (R.wave === 0 || (!R.alive.length)) { R.t -= dt; if (R.wave >= R.waves) { this.raid = null; p.addEffect('hero', R.lvl, 2400); const em = 4 + Math.floor(Math.random() * 5) + R.lvl * 2; dropItem(p.pos.x, p.pos.y + 1, p.pos.z, IID.emerald, em); if (Math.random() < 0.35) dropItem(p.pos.x, p.pos.y + 1, p.pos.z, IID.totem, 1); Snd.play('levelup', 0.9); UI.toast('Vitória! Você é o Herói da Vila!'); }
        else { UI.bossBar('Invasão — próxima onda em ' + Math.ceil(Math.max(0, R.t)) + 's', R.wave === 0 ? 0 : 1 - Math.max(0, R.t) / 8); if (R.t <= 0) { raidWave(R); R.t = 8; } } }
      else { UI.bossBar('Invasão — Onda ' + R.wave + '/' + R.waves + ' · ' + R.alive.length + ' invasores', hp / Math.max(1, R.maxHp)); for (const e of R.alive) if (Math.hypot(e.pos.x - R.x, e.pos.z - R.z) > 140) { e.remove(); } }
    }
  }
  return _lp.apply(this, arguments);
};

