    for (const [x, y, w, h] of [[12, 11, 3, 3], [17, 13, 2, 2], [14, 17, 4, 3], [19, 18, 2, 2], [11, 19, 2, 2], [18, 10, 1, 1]]) { g.fillStyle = 'rgb(150,156,172)'; g.fillRect(x, y, w, h); g.fillStyle = 'rgb(176,182,198)'; g.fillRect(x, y, w, 1); }
