    if (ph !== 4) { g.fillStyle = 'rgba(190,205,255,0.10)'; g.fillRect(7, 7, 18, 2); g.fillRect(7, 23, 18, 2); g.fillRect(7, 9, 2, 14); g.fillRect(23, 9, 2, 14); }
