    if (GEAR[e.type].weapon && Math.random() < [0, 0.03, 0.06, 0.1][d] * moon) { let tot = WEAP.reduce((s, w) => s + w[1], 0), k = Math.random() * tot; for (const [w, wt] of WEAP) { k -= wt; if (k <= 0) { if (IID[w] !== undefined) g.h = IID[w]; break; } } }
